.rad-fx-typing {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 12px 16px;
    border-radius: 18px;
    background: rgba(127, 127, 127, 0.18);
}

.rad-fx-typing-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--rad-fx-typing-color, currentColor);
    animation: rad-fx-typing 1.2s ease-in-out infinite;
}

.rad-fx-typing-dot:nth-of-type(2) { animation-delay: 0.15s; }
.rad-fx-typing-dot:nth-of-type(3) { animation-delay: 0.3s; }

@keyframes rad-fx-typing {
    0%, 60%, 100% { transform: translateY(0); opacity: 0.45; }
    30% { transform: translateY(-5px); opacity: 1; }
}

/* Reduced motion: no bouncing, just a slow fade so it still reads as "live". */
@media (prefers-reduced-motion: reduce) {
    .rad-fx-typing-dot { animation: rad-fx-typing-fade 2s ease-in-out infinite; }
}

[data-rad-fx-motion='reduce'] .rad-fx-typing-dot { animation: rad-fx-typing-fade 2s ease-in-out infinite; }

@keyframes rad-fx-typing-fade {
    0%, 100% { opacity: 0.45; }
    50% { opacity: 1; }
}
